import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"eqsat — the equality-saturation substrate","description":"","frontmatter":{},"headers":[],"relativePath":"eqsat/index.md","filePath":"vendored/eqsat/index.md"}`),a={name:`eqsat/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="eqsat-—-the-equality-saturation-substrate" tabindex="-1">eqsat — the equality-saturation substrate <a class="header-anchor" href="#eqsat-—-the-equality-saturation-substrate" aria-label="Permalink to “eqsat — the equality-saturation substrate”">​</a></h1><p><strong>eqsat</strong> is the substrate the mlopt game is played on: the torch-free semantic engine extracted from <code>graphopt</code> at the plan-0032 phase-4 repo split (<code>research-mlopt</code> → <code>graphopt</code> → three public repos). It owns the <em>representation and the machinery</em> — term IR, e-graph, the law bank and its admission machinery, the cost algebra, and the ports — plus the backend-neutral pipeline that runs search over them. Domain repos bring the backends and the boards; eqsat brings everything that must not know them.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to “What&#39;s inside”">​</a></h2><table tabindex="0"><thead><tr><th>package</th><th>role</th></tr></thead><tbody><tr><td><code>mlopt-core</code></td><td>term IR (<code>mlopt_core.ir</code>), the e-graph (<code>mlopt_core.egraph</code> — <code>EGraph</code>, <code>run</code>, <code>extract_best</code>, <code>certificate</code>/<code>verify_certificate</code>), the law bank + machinery (<code>mlopt_core.laws</code> — <code>DEFAULT</code>, <code>ALL_RULES</code>, <code>provenance</code>, <code>cond</code>/<code>tensor</code>/<code>minted</code>), the cost algebra (<code>mlopt_core.cost</code> — <code>dag_cost</code> + the shipped models), attrs, typing, and the ports (<code>mlopt_core.ports</code> — <code>Sink</code>, <code>Source</code>, <code>Engine</code>, <code>Composer</code>, <code>Executor</code>, …). Stdlib-only.</td></tr><tr><td><code>mlopt-orchestrator</code></td><td>the backend-neutral pipeline (<code>search</code>, <code>lower</code>, <code>Optimizer</code>, strategies <code>Monolithic</code>/<code>Compositional</code>/<code>Autotuned</code>, the criteria family). Depends on <code>mlopt-core</code> alone.</td></tr><tr><td><code>mlopt-native</code></td><td>the optional PyO3/Rust search engine behind <code>engine=</code> (<code>mlopt_native.NativeEngine</code>). Excluded from the uv workspace — build with <code>maturin develop --release</code>.</td></tr></tbody></table><h2 id="how-it-s-consumed" tabindex="-1">How it&#39;s consumed <a class="header-anchor" href="#how-it-s-consumed" aria-label="Permalink to “How it&#39;s consumed”">​</a></h2><p><code>graphopt</code> pins the packages as git dependencies on <code>packages/</code> subdirectories — <code>uv sync</code> in a <code>graphopt</code> clone resolves them automatically; there is nothing separate to install. Working on the substrate itself:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">git</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> clone</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> https://github.com/handl-lang/eqsat</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">cd</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> eqsat</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">uv</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> sync</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --group</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> dev</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> pytest</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> tests/</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -q</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">     #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> the substrate suite</span></span></code></pre></div><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to “Read next”">​</a></h2><ul><li><a href="./explanation/egraph.html">The e-graph and <code>dag_cost</code></a> — saturation as a closure, extraction, honest pricing.</li><li><a href="./explanation/certificates.html">Certificates</a> — the replayable derivation that is the claim.</li><li><a href="./explanation/ports.html">The ports</a> — <code>Source</code>/<code>Sink</code>/<code>Engine</code>: how backends plug into a substrate that never imports them.</li><li>Reference: <a href="./reference/egraph.html">the e-graph</a> · <a href="./reference/cost.html">the cost algebra</a> · <a href="./reference/ports.html">the ports</a> · <a href="./reference/frozen-api.html">the frozen API slice</a> — the substrate rows of the phase-1 contract.</li><li>The whole-system account stays with graphopt: <a href="/docs/graphopt/explanation/mechanism.html">how mlopt works</a>.</li><li>Source: <a href="https://github.com/handl-lang/eqsat" target="_blank" rel="noreferrer"><code>handl-lang/eqsat</code></a>.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};